import{showcaseHTML}from'./showcase.js';
import{nextStep}from'./workflow.js';
import{scanFolder,importPapers}from'./folder-import.js';
import{Workspace,writeFile,maybeJSON}from'./storage.js';import{extractPDF}from'./pdf.js';import{safeUrl,digest,SECTION_LABELS,fingerprint,reportMarkdown}from'./core.js';import{listModels,analyzePaper,synthesize,generate}from'./analysis.js';import{zip}from'./zip.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let ws=null,professors=[],selected=null,view='library',tab='papers',query='',edit=null,busy=false,controller=null,config={provider:'gemini',key:'',model:''},models=[],pdfURL='',currentResult=null,renderSeq=0;const content=$('#content');const current=()=>professors.find(p=>p.id===selected);function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',7000)}function link(u,t){return safeUrl(u)?`<a href="${esc(safeUrl(u))}" target="_blank" rel="noopener noreferrer">${esc(t)} ↗</a>`:'<span class="hint">未提供來源連結</span>'}function download(name,data,type='text/plain'){let u=URL.createObjectURL(data instanceof Blob?data:new Blob([data],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function progress(t){$('#jobText').textContent=t}async function job(label,fn){if(busy)return;busy=true;controller=new AbortController();$('#job').hidden=false;progress(label);$('#analysisError')?.remove();document.querySelectorAll('.nav,#connect,#refresh,#providerSelect,#modelSelect,#apiKey').forEach(x=>x.disabled=true);try{await fn(controller.signal);await render()}catch(e){toast(e.message);if(ws){try{professors=await ws.list();await render()}catch{}}showAnalysisError(e)}finally{busy=false;$('#job').hidden=true;document.querySelectorAll('.nav,#connect,#refresh,#providerSelect,#modelSelect,#apiKey').forEach(x=>x.disabled=false);controller=null}}
const publicNav=document.createElement('button');publicNav.className='nav';publicNav.dataset.view='public';publicNav.textContent='▤　公開研究庫';document.querySelector('.nav').before(publicNav);
$('#cancelJob').onclick=()=>controller?.abort();$('#connect').onclick=async()=>{if(!window.showDirectoryPicker){toast('實體資料夾功能需要桌面 Chrome／Edge，請以獨立 HTTPS 頁面開啟。');return}try{let h=await window.showDirectoryPicker({mode:'readwrite',id:'scholar-atlas-v2'});await job('開啟實體資料夾…',async()=>{ws=await Workspace.open(h);professors=await ws.list();selected=null;view='library';$('#folderStatus').textContent=h.name+'/scholar-atlas-data/';$('#connect').textContent='切換資料夾';$('#refresh').hidden=false})}catch(e){if(e.name!=='AbortError')toast('無法開啟資料夾：'+e.message)}};$('#refresh').onclick=()=>job('重新讀取資料…',async()=>{professors=await ws.list();if(!current())selected=null;toast('已重新讀取磁碟資料')});document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>{if(busy)return;view=b.dataset.view;if(view!=='model')selected=null;render()});$('#closeDialog').onclick=$('#cancel').onclick=()=>{if(!busy)$('#editor').close()};$('#editor').addEventListener('cancel',e=>{if(busy)e.preventDefault()});$('#closeEvidence').onclick=()=>{$('#evidence').close();if(pdfURL)URL.revokeObjectURL(pdfURL);pdfURL=''};
async function render(){let seq=++renderSeq;document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#modelStatus').textContent=config.key&&config.model?'模型已選擇：'+config.model:'模型尚未設定';$('#crumb').textContent=view==='library'?(current()?.name||'我的教授'):({model:'AI 設定',guide:'使用說明'}[view]);if(view==='public'){content.innerHTML=showcaseHTML();$('#crumb').textContent='公開研究庫';return}if(view==='model')return modelView();if(view==='guide')return guide();if(current())return detail(seq);library()}
function library(){if(!ws){content.innerHTML=showcaseHTML();return}let total=professors.reduce((a,p)=>a+p.papers.length,0),done=professors.reduce((a,p)=>a+p.papers.filter(q=>q.analysisAt).length,0);content.innerHTML=`<section class="hero"><div><h1>我的教授</h1><p>管理論文、分析與申請筆記。</p></div><div class="actions"><button class="primary" data-act="import-folder">匯入教授資料夾</button><button data-act="add-prof">＋ 新增教授</button></div></section><div class="stats"><div class="stat"><div class="stat-icon">▱</div><div><strong>${professors.length}</strong><small>教授</small></div></div><div class="stat"><div class="stat-icon">▤</div><div><strong>${total}</strong><small>論文</small></div></div><div class="stat"><div class="stat-icon">✓</div><div><strong>${done}</strong><small>已分析</small></div></div></div><div class="toolbar"><input id="search" aria-label="搜尋教授" placeholder="搜尋教授、學校、Program" value="${esc(query)}"></div><div class="grid" id="cards"></div><section class="panel"><h3>我的申請研究方向</h3><p>用於整理研究契合度。</p><textarea id="interests" aria-label="申請研究方向" placeholder="例如：結合運籌最佳化與機器學習，研究受限制的決策問題。">${esc(ws.settings.interests)}</textarea><button style="margin-top:12px" data-act="save-interests">儲存研究方向</button></section>`;cards();$('#search').oninput=e=>{query=e.target.value;cards()}}
function cards(){$('#cards').innerHTML=professors.filter(p=>[p.name,p.school,p.program].join(' ').toLowerCase().includes(query.toLowerCase())).map(p=>`<article class="card"><div class="card-top"><div class="avatar">${esc(p.name.slice(0,2))}</div></div><h2>${esc(p.name)}</h2><div class="school">${esc(p.school)} · ${esc(p.program)}</div><p>${p.papers.filter(q=>q.hasPDF).length} 份原文 PDF<br>${p.papers.filter(q=>q.analysisAt).length} 篇已分析</p><div class="card-bottom"><span>▤ ${p.papers.length} 篇論文</span><button data-act="open" data-id="${esc(p.id)}">查看 →</button></div></article>`).join('')+`<button class="card add-card" data-act="add-prof"><span class="plus">＋</span><h3>新增一位教授</h3></button>`}
async function detail(seq){let p=current();content.innerHTML=`<section class="hero"><div><div class="eyebrow"><a href="#" data-act="back">← 教授資料夾</a></div><h1>${esc(p.name)}</h1><p>${esc(p.school)} · ${esc(p.program)}　${link(p.url,'官方頁面')}</p></div><div class="actions"><button class="primary" data-act="add-paper">＋ 加入 PDF／來源</button><details class="more-actions"><summary>教授資料與匯出</summary><button data-act="edit-prof">編輯教授資料</button><button data-act="zip">下載完整資料夾 ZIP</button></details></div></section>${workflowPanel(p)}<div class="tabs">${[['papers','論文與逐篇分析'],['synthesis','研究概要'],['notes','申請筆記']].map(([k,n])=>`<button data-act="tab" data-id="${k}" class="${tab===k?'selected':''}">${n}</button>`).join('')}</div><div id="detailBody"></div>`;let d=$('#detailBody');if(tab==='papers'){d.innerHTML=`<div class="panel"><h2>論文與原文分析</h2>${[...p.papers].sort((a,b)=>(b.year||0)-(a.year||0)).map(q=>`<article class="paper"><div class="year">${esc(q.year||'未填')}</div><div><h3>${esc(q.title)}</h3><span class="badge ${q.analysisAt?'green':''}">${q.analysisAt?'已分析 · '+q.analysisCount+' 條主張':q.hasPDF?'已讀取 '+q.pageCount+' 頁':'僅來源連結'}</span><p>${q.hasPDF?`PDF：${esc(q.originalName)}${q.lowPages?.length?' · '+q.lowPages.length+' 頁文字稀少':''}`:'加入 PDF 後可分析。'}</p>${link(q.url,'論文來源')}</div><div class="actions paper-actions"><button data-act="edit-paper" data-id="${esc(q.id)}">編輯資料／補上 PDF</button>${q.hasPDF?`<button data-act="reset-paper-progress" data-id="${esc(q.id)}">清除暫存進度</button><button data-act="read" data-id="${esc(q.id)}">閱讀原文</button><button class="primary" data-act="analyze" data-id="${esc(q.id)}">${q.analysisAt?'重新分析':'分析／接續'}</button>`:''}${q.analysisAt?`<button data-act="analysis" data-id="${esc(q.id)}">查看分析</button>`:''}<button class="danger" data-act="archive-paper" data-id="${esc(q.id)}">移到封存</button></div></article>`).join('')||'<div class="empty">尚無論文。請加入 PDF 或來源連結。</div>'}</div><p class="hint">掃描 PDF 需先 OCR；圖表與公式請回查原文。</p><button class="danger" data-act="archive-prof">封存教授資料夾</button>`}else if(tab==='notes'){d.innerHTML=`<div class="panel"><h2>我的申請筆記</h2><p>記錄研究想法與聯絡教授的問題。</p><textarea id="notes" style="min-height:300px" aria-label="申請筆記">${esc(p.notes||'')}</textarea><button class="primary" data-act="save-notes">儲存筆記</button></div>`}else{d.innerHTML='<div class="panel">讀取已儲存概要…</div>';let result=await ws.synthesis(p);if(seq!==renderSeq)return;currentResult=result;let available=p.papers.filter(q=>q.analysisAt);d.innerHTML=`<div class="panel"><h2>跨論文研究分析</h2><p>以已分析的論文為材料，歸納主軸、研究演進、共同方法與申請方向關聯。每條結論保留可回查的原文引用。</p><label class="field">你的申請研究方向<textarea id="interests" placeholder="例如：運籌最佳化與機器學習、供應鏈決策。">${esc(ws.settings.interests)}</textarea></label><button data-act="save-interests">儲存申請方向</button><p class="hint">儲存後套用至新概要；留空則不做個人化比對。</p><div class="selection">${available.map(q=>`<label><input type="checkbox" name="selectedPaper" value="${esc(q.id)}" checked> ${esc(q.title)} (${q.year||'年份未填'})</label>`).join('')||'<p>請先完成至少兩篇論文的原文分析。</p>'}</div><button data-act="reset-synthesis-progress">清除概要暫存</button><button class="primary" data-act="synthesize" ${available.length<2?'disabled':''}>產生研究概要</button></div>${result?`${result.fingerprint!==fingerprint(p,ws.settings.interests)?'<div class="notice warning">資料或申請方向已更新；以下是先前保存的概要，請重新分析。</div>':''}<div class="actions"><button data-act="download-synthesis">↓ 下載概要 Markdown</button></div>${reportHTML(result,p.papers)}`:''}`}}
function reportHTML(r,papers){return `<div class="notice"><b>AI 分析，請核對原文。</b><br>模型：${esc(r.model)} · ${esc(new Date(r.createdAt).toLocaleString('zh-TW',{timeZone:'Asia/Taipei'}))}<br>${esc(r.coverage)}<br>已排除無法核對的主張：${r.rejected?.length||0}</div>`+Object.entries(SECTION_LABELS).map(([k,n])=>{let claims=r.claims.filter(c=>c.section===k);return claims.length?`<section class="panel"><h2>${n}</h2>${claims.map(c=>`<div class="claim"><span class="badge ${c.kind==='evidence'?'green':''}">${c.kind==='evidence'?'依原文整理':'推論／建議'}</span><p>${esc(c.text)}</p><div class="citations">${c.citations.map(ref=>`<button data-act="cite" data-id="${esc(ref.paperId)}" data-page="${ref.page}" data-quote="${esc(ref.quote)}">${esc(papers.find(q=>q.id===ref.paperId)?.title||ref.paperId)} · PDF p.${ref.page} ↗</button>`).join('')}</div></div>`).join('')}</section>`:''}).join('')+`<div class="panel"><h3>涵蓋範圍與限制</h3><p class="pre">${esc(r.gaps||'未另列')}</p><p class="hint">引用採 PDF 頁次。圖表、公式與排版可能影響擷取。</p></div>`}
function providerName(){return config.provider==='openai'?'OpenAI':'Google Gemini'}
function modelView(){content.innerHTML=`<section class="hero"><div><h1>AI 設定</h1><p>選擇 AI 服務，分析論文原文。</p></div></section><section class="panel"><label class="field">AI 服務<select id="providerSelect"><option value="gemini" ${config.provider==='gemini'?'selected':''}>Google Gemini</option><option value="openai" ${config.provider==='openai'?'selected':''}>OpenAI（GPT）</option></select></label><h2>${providerName()} API 金鑰</h2><p>金鑰僅保留於此分頁，重新整理後需重填。分析文字會傳送至 ${providerName()}，依你的 API 額度與方案計費。</p><p>${config.provider==='openai'?link('https://platform.openai.com/api-keys','取得 OpenAI API 金鑰'):link('https://aistudio.google.com/apikey','取得 Gemini API 金鑰')}</p><label class="field">API Key<input id="apiKey" type="password" autocomplete="off" placeholder="輸入你自己的 ${providerName()} API key"></label><div class="actions" style="margin-top:14px"><button data-act="verify-key" class="primary">連接 ${providerName()}</button><button data-act="clear-key">清除金鑰</button></div><p class="hint">${config.key?'已連接；留空可沿用本次金鑰。':'請輸入自己的金鑰。'}</p>${models.length?`<label class="field">選擇模型<select id="modelSelect">${models.map(m=>`<option ${config.model===m?'selected':''}>${esc(m)}</option>`).join('')}</select></label><button data-act="test-model" style="margin-top:14px">測試模型（選用）</button><p class="hint">模型清單不保證支援結構化輸出。使用合成文字測試引用格式，不傳送論文；暫時性錯誤最多重試 2 次，可能增加用量。</p>`:''}</section>${current()?`<section class="panel resume-panel"><div><h3>${esc(current().name)}</h3><p>${config.key&&config.model?'已就緒，可開始分析。':'設定後即可分析。'}</p></div><button class="primary" data-act="return-professor">返回論文 →</button></section>`:''}`;$('#providerSelect').onchange=e=>{if(busy)return;config={provider:e.target.value,key:'',model:''};models=[];render()};if($('#modelSelect'))$('#modelSelect').onchange=e=>{config.model=e.target.value;$('#modelStatus').textContent='模型已選擇：'+config.model}}
function guide(){content.innerHTML=`<section class="hero"><div><h1>使用說明</h1></div></section><section class="panel"><h2>三步完成整理</h2><ol><li>匯入教授資料夾，確認姓名與 PDF。</li><li>設定 Gemini 或 OpenAI 金鑰，分析論文並核對引用。</li><li>完成至少兩篇分析，填寫申請方向並產生研究概要。</li></ol></section><section class="panel"><h2>資料與隱私</h2><p>資料保存在電腦的 scholar-atlas-data。下次選取此資料夾或它的父資料夾，即可繼續使用。</p><p>匯入與閱讀不需金鑰。執行 AI 分析前會確認傳送範圍；金鑰不寫入磁碟。</p></section><section class="panel"><h2>閱讀限制</h2><p>掃描 PDF 需先 OCR。圖表、公式與排版可能影響擷取；AI 結論請回查原文。</p><p>來源連結不會自動下載。封存資料可從研究庫的 trash 資料夾取回。</p></section><section class="panel"><h2>專案文件</h2><div class="doclinks"><a href="AGENTS.md" download>開發規則</a><a href="README.md" download>使用手冊</a><a href="scholar-atlas-source.zip" download>下載原始碼</a></div></section>`}

const input=(n,l,v='',t='text',required=false)=>`<label class="field">${l}<input name="${n}" type="${t}" value="${esc(v)}" ${required?'required':''} ${t==='number'?'min="1900" max="2200"':''}></label>`;
function editor(kind,x={}){if(!ws){toast('請先選取電腦資料夾');return}edit={kind,id:x.id};$('#dialogTitle').textContent=(x.id?'編輯':'新增')+(kind==='prof'?'教授資料':'論文與原文');$('#fields').innerHTML=kind==='prof'?input('name','教授姓名 *',x.name,'text',true)+input('school','學校',x.school)+input('program','Program／系所',x.program)+input('url','官方研究頁面',x.url,'url'):input('title','論文標題 *',x.title,'text',true)+input('year','所收錄版本的發表年份（可留空）',x.year||'','number')+input('url','原始論文／DOI 來源連結',x.url,'url')+`<label class="field">原文 PDF（50 MB 以下；掃描檔需先 OCR）<input name="pdf" type="file" accept=".pdf,application/pdf" ${x.hasPDF?'disabled':''}></label>${x.hasPDF?'<p class="hint">已保存原文。若要替換為不同版本，請新增一筆論文，以免破壞既有引用。</p>':''}<label class="check"><input name="authorship" type="checkbox" required ${x.authorship?'checked':''}>確認教授為作者之一，且有權保存 PDF。</label><p class="hint">僅有連結可保存，分析需 PDF。</p>`;$('#editor').showModal()}
$('#editForm').onsubmit=async e=>{e.preventDefault();if(busy)return;let f=new FormData(e.target),p=current(),meta={};for(let k of edit.kind==='prof'?['name','school','program','url']:['title','url'])meta[k]=String(f.get(k)||'').trim();if(meta.url&&!safeUrl(meta.url)){toast('網址須為 HTTP／HTTPS');return}if(edit.kind==='prof'&&!meta.name||edit.kind==='paper'&&!meta.title){toast('請填寫必要欄位');return}if(edit.kind==='paper'){meta.year=f.get('year')?Number(f.get('year')):null;if(meta.year!==null&&(!Number.isInteger(meta.year)||meta.year<1900||meta.year>2200)){toast('年份無效');return}meta.authorship=f.get('authorship')==='on';if(!meta.authorship){toast('請確認作者與檔案使用權');return}if(p.papers.some(q=>q.id!==edit.id&&(q.title.toLowerCase()===meta.title.toLowerCase()||(meta.url&&q.url===meta.url)))){toast('此標題或來源連結已收錄');return}}await job('儲存資料…',async signal=>{if(edit.kind==='prof'){if(edit.id){Object.assign(p,meta);await ws.saveProfessor(p)}else{let added=await ws.addProfessor({...meta,notes:''});professors.push(added);selected=added.id;tab='papers'}}else{let old=p.papers.find(q=>q.id===edit.id),q={...old,...meta,id:edit.id||crypto.randomUUID(),hasPDF:old?.hasPDF||false},file=f.get('pdf'),pages=null;if(file?.size&&!old?.hasPDF){pages=await extractPDF(file,(n,total)=>progress(`擷取 PDF 第 ${n} / ${total} 頁`),signal);q.hash=await digest(await file.arrayBuffer());q.textHash=await digest(JSON.stringify(pages));if(p.papers.some(x=>x.id!==q.id&&x.hash===q.hash))throw Error('此 PDF 已收錄在同一位教授的資料夾');q.hasPDF=true;q.originalName=file.name;q.pageCount=pages.length;q.lowPages=pages.filter(x=>x.text.trim().length<30).map(x=>x.page);q.status='extracted'}if(!q.hasPDF&&!q.url)throw Error('請提供 PDF 或論文來源連結');if(signal.aborted)throw Error('已取消，未建立論文');if(old){if(file?.size&&!old.hasPDF){let dir=await ws.paperDir(p,q);await writeFile(dir,'original.pdf',file);await writeFile(dir,'pages.json',JSON.stringify(pages,null,2))}Object.assign(old,q);await ws.savePaper(p,old)}else await ws.addPaper(p,q,file?.size?file:null,pages)}$('#editor').close();toast('已寫入實體資料夾')})};
async function evidence(p,q,page=1,quote=''){let pages=await ws.pages(p,q);if(!Number.isInteger(page)||page<1||page>pages.length)throw Error('引用頁碼不在 PDF 範圍內');if(pdfURL)URL.revokeObjectURL(pdfURL);pdfURL=URL.createObjectURL(await ws.pdf(p,q));$('#evidenceTitle').textContent=q.title;$('#evidenceBody').innerHTML=`<div class="toolbar"><label>PDF 頁次 <select id="pageSelect">${pages.map(pg=>`<option value="${pg.page}" ${pg.page===page?'selected':''}>${pg.page} / ${pages.length}${pg.label!==String(pg.page)?'（標籤 '+esc(pg.label)+'）':''}</option>`).join('')}</select></label><a href="${pdfURL}" download="${esc(q.originalName)}">下載原始 PDF</a></div>${quote?`<blockquote>${esc(quote)}</blockquote><p class="hint">引文已核對；請閱讀上下文確認語意。</p>`:''}<div class="evidence-grid"><iframe id="pdfFrame" title="PDF 原文" src="${pdfURL}#page=${page}"></iframe><div><h3>該頁擷取文字</h3><pre id="pageText">${esc(pages[page-1].text||'此頁沒有可擷取文字，需要先 OCR。')}</pre></div></div>`;$('#pageSelect').onchange=e=>{let n=Number(e.target.value);$('#pdfFrame').src=pdfURL+'#page='+n;$('#pageText').textContent=pages[n-1].text||'此頁沒有可擷取文字，需要先 OCR。'};$('#evidence').showModal()}
async function exportFolder(p){let entries=[];async function walk(dir,path){for await(let[n,h]of dir.entries()){if(h.kind==='directory')await walk(h,path+'/'+n);else entries.push([path+'/'+n,await h.getFile()])}}await walk(await ws.profDir(p),p.folder);download(p.folder+'.zip',await zip(entries));toast('已匯出磁碟中的完整教授資料夾')}
function requireModel(){if(!config.key||!config.model){view='model';render();toast('先設定 AI，再按「返回教授，繼續分析」。已匯入的資料不會遺失。');return false}return true}
document.addEventListener('click',async e=>{let b=e.target.closest('[data-act]');if(!b)return;e.preventDefault();if(busy){toast('目前正在處理，請等待或取消');return}let a=b.dataset.act,k=b.dataset.id,p=current(),q=p?.papers.find(x=>x.id===k);try{if(a==='reset-paper-progress'||a==='reset-synthesis-progress'){if(confirm('只清除未完成的分析進度，保留 PDF 與已完成分析。下次會重新呼叫 API。繼續？')){await ws.clearProgress(p,a==='reset-paper-progress'?q:null);toast('已清除暫存進度')}return}if(a==='setup-model'){view='model';await render()}if(a==='return-professor'){view='library';await render()}if(a==='go-synthesis'){tab='synthesis';await render()}if(a==='analyze-pending')await analyzePending(p);if(a==='import-folder')await chooseProfessorFolder();if(a==='connect')$('#connect').click();if(a==='add-prof')editor('prof');if(a==='edit-prof')editor('prof',p);if(a==='open'){selected=k;tab='papers';await render()}if(a==='back'){selected=null;await render()}if(a==='tab'){tab=k;await render()}if(a==='add-paper')editor('paper');if(a==='edit-paper')editor('paper',q);if(a==='read'||a==='cite')await evidence(p,q,Number(b.dataset.page||1),b.dataset.quote||'');if(a==='save-interests'){ws.settings.interests=$('#interests').value;await ws.saveSettings();toast('申請方向已儲存');await render()}if(a==='save-notes'){p.notes=$('#notes').value;await ws.saveProfessor(p);await writeFile(await ws.profDir(p),'application-notes.md',p.notes);toast('已儲存申請筆記')}if(a==='zip')await job('打包實體資料夾…',()=>exportFolder(p));if(a==='archive-paper'||a==='archive-prof'){if(confirm('將資料移至工作區的 trash 封存目錄？原始檔仍會保留在電腦，可自行取回。'))await job('封存資料…',async()=>{await ws.archive(p,a==='archive-paper'?q:null);professors=await ws.list();if(a==='archive-prof')selected=null})}if(a==='verify-key'){let key=$('#apiKey').value.trim()||config.key;if(!key)throw Error('請輸入 API key');await job('驗證金鑰並查詢模型…',async signal=>{let found=await listModels(key,signal,config.provider);models=found.filter(m=>!/(image|audio|tts|robotics)/i.test(m));if(!models.length)throw Error('此金鑰沒有可用的文字生成模型');config={provider:config.provider,key,model:models[0]};toast('已讀取模型清單；請測試模型是否支援結構化分析')})}if(a==='clear-key'){config={provider:config.provider,key:'',model:''};models=[];render();toast('已清除金鑰')}if(a==='test-model'){if(!requireModel())return;await job('測試真實模型生成…',async signal=>{const sample='This synthetic benchmark evaluates a scheduling method on generated tasks.';const result=await generate({...config,onProgress:progress},`這是合成連線測試，不是真實論文。根據材料回傳一條 method 主張，kind=evidence，引用 paperId=test、page=1、quote=${sample}。gaps 留空。材料：${sample}`,signal);if(!result.claims.length||result.claims[0].citations?.[0]?.quote!==sample)throw Error('連線成功，但結構化引用測試未通過');toast('結構化分析測試成功；長論文仍可能受服務狀態影響')})}if(a==='analyze'){if(!requireModel())return;await ws.pdf(p,q);let pages=await ws.pages(p,q),n=pages.filter(x=>x.text.trim()).length;if(!n)throw Error('這份 PDF 沒有可擷取文字，請先 OCR');if(!confirm(`將「${q.title}」共 ${pages.length} 頁的擷取文字送至 ${providerName()}（${config.model}）分析，使用你的 API 額度。圖像不會送出。暫時性服務錯誤最多重試 2 次；輸出過長會調整額度或拆段，可能增加 API 用量。已完成片段可接續。繼續？`))return;await job('準備原文分析…',async signal=>{let result=await analyzePaper(analysisConfig(p,q),q,pages,progress,signal);if(signal.aborted)throw Error('已取消，未覆寫分析');await ws.saveAnalysis(p,q,result,reportMarkdown(q.title,result,p.papers));toast('原文分析已儲存；請查看引用並核對語意')})}if(a==='analysis'){let result=await ws.analysis(p,q);if(!result)throw Error('找不到 analysis.json，請重新分析');currentResult=result;content.innerHTML=`<section class="hero"><div><div class="eyebrow"><a href="#" data-act="return-detail">← 返回論文</a></div><h1>${esc(q.title)}</h1><p>AI 分析 · 請核對原文</p></div><button data-act="download-analysis" data-id="${esc(q.id)}">↓ 下載分析</button></section>${reportHTML(result,p.papers)}`;}if(a==='return-detail')await render();if(a==='download-analysis'){let r=await ws.analysis(p,q);download(q.id+'-analysis.md',reportMarkdown(q.title,r,p.papers))}if(a==='download-synthesis'){let r=await ws.synthesis(p);download(p.name+'-synthesis.md',reportMarkdown(p.name+' 研究概要',r,p.papers))}if(a==='synthesize'){if(!requireModel())return;let ids=[...document.querySelectorAll('input[name="selectedPaper"]:checked')].map(x=>x.value);if(ids.length<2)throw Error('請至少選取兩篇已分析論文');if(ids.length>20)throw Error('每次最多選取 20 篇，避免超過模型上下文');if(!confirm(`將 ${ids.length} 篇論文的分析與原文引文，以及你的申請研究方向送至 ${providerName()}，使用 API 額度。服務錯誤最多重試 2 次；輸出上限可能提高，增加用量。已完成主題可接續。繼續？`))return;await job('載入已分析原文證據…',async signal=>{let docs=[];for(let id of ids){let paper=p.papers.find(x=>x.id===id),analysis=await ws.analysis(p,paper);if(!analysis||analysis.pdfHash!==paper.hash)throw Error('部分論文分析缺失或版本不符，請先重新分析');await ws.pdf(p,paper);docs.push({...paper,pages:await ws.pages(p,paper),analysis})}let result=await synthesize(analysisConfig(p),p,docs,ws.settings.interests,progress,signal);if(signal.aborted)throw Error('已取消，未覆寫概要');await ws.saveSynthesis(p,result,reportMarkdown(p.name+' 研究概要',result,p.papers));toast('跨論文概要已寫入教授資料夾')})}}catch(e){toast(e.message)}});render();

let pendingFolder=null;
async function chooseProfessorFolder(){
 if(!window.showDirectoryPicker){toast('請用桌面 Chrome／Edge 直接開啟 HTTPS 網站');return}
 try{
  const handle=await window.showDirectoryPicker({mode:ws?'read':'readwrite',id:'scholar-atlas-import'});
  if((await maybeJSON(handle,'workspace.json'))?.version===2){toast('這是既有研究庫，請按「開啟既有研究庫」，不要當作新的教授資料夾匯入');return}
  let scanned;
  await job('掃描教授資料夾…',async()=>{scanned=await scanFolder(handle)});
  if(!scanned)return;
  if(!scanned.files.length){toast('找不到 PDF。若要恢復資料，請開啟研究庫。');return}
  pendingFolder={handle,...scanned};
  $('#bulkName').value=handle.name;$('#bulkRights').checked=false;
  $('#bulkDestination').textContent=ws?'儲存至目前研究庫。':'儲存位置：所選資料夾內的 scholar-atlas-data。原檔保留。';
  $('#bulkList').textContent=`找到 ${scanned.files.length} 份 PDF，忽略 ${scanned.ignored} 個其他檔案。請確認教授名稱。\n\n`+scanned.files.map(f=>f.path).join('\n');
  $('#bulk').showModal();
 }catch(e){if(e.name!=='AbortError')toast(e.name==='SecurityError'?'瀏覽器不允許選取資料夾。請用桌面 Chrome／Edge 直接開啟網站，不要使用嵌入預覽。':e.message)}
}
$('#bulkCancel').onclick=()=>{$('#bulk').close();pendingFolder=null};
$('#bulkForm').onsubmit=async e=>{
 e.preventDefault();if(busy||!pendingFolder)return;
 const name=$('#bulkName').value.trim();if(!name||!$('#bulkRights').checked)return;
 const source=pendingFolder;
 const matches=professors.filter(p=>p.name===name);
 if(matches.length>1){toast('存在多位同名教授，請修改名稱以避免合併錯誤');return}
 if(matches.length&&!confirm('同名教授已存在，將把 PDF 加入 '+name+' 的現有資料夾，重複 PDF 會略過。繼續？'))return;
 $('#bulk').close();pendingFolder=null;
 let results;
 await job('建立教授並匯入 PDF…',async signal=>{
  if(!ws){ws=await Workspace.open(source.handle);professors=await ws.list();$('#folderStatus').textContent=source.handle.name+'/scholar-atlas-data/';$('#refresh').hidden=false;$('#connect').textContent='切換研究庫'}
  const existing=professors.filter(p=>p.name===name);
  if(existing.length>1)throw Error('研究庫有多位同名教授，請改名後再匯入');
  if(existing.length&&!matches.length&&!confirm('此研究庫已有同名教授，將合併論文並略過重複 PDF。繼續？'))return;let p=existing[0];if(!p){p=await ws.addProfessor({name,school:'',program:'',url:'',notes:''});professors.push(p)}
  selected=p.id;view='library';tab='papers';
  results=await importPapers({ws,professor:p,files:source.files,extract:extractPDF,signal,progress});
 });
 if(results){$('#bulkResult').querySelector('h2').textContent='批次匯入結果';$('#bulkResultText').textContent=results.map(r=>`${r.status}｜${r.path}｜${r.message}`).join('\n');$('#bulkSummary').textContent=['成功','略過','失敗','未處理'].map(k=>k+' '+results.filter(r=>r.status===k).length).join(' · ');$('#bulkResult').showModal()}
};
$('#bulkResultClose').onclick=()=>$('#bulkResult').close();

function workflowPanel(p){
 const step=nextStep(p.papers,{modelReady:!!(config.key&&config.model),interests:ws.settings.interests});
 const count=p.papers.filter(q=>q.hasPDF).length,done=p.papers.filter(q=>q.analysisAt).length;
 return `<section class="panel next-step"><ol class="journey" aria-label="研究整理流程">${['匯入 PDF','設定 AI','逐篇分析','研究概要'].map((label,i)=>`<li ${step.stage===i+1?'aria-current="step"':''}><span>${i+1}</span>${label}</li>`).join('')}</ol><div class="resume-panel"><div><h2>下一步</h2><p>${esc(step.text)}</p><small class="hint">${count} 篇 PDF · ${done} 篇已分析 · ${config.key&&config.model?'AI 已設定':'AI 未設定'}</small></div><button class="primary" data-act="${step.action}">${esc(step.label)} →</button></div></section>`;
}
async function analyzePending(p){
 if(!requireModel())return;
 const pending=p.papers.filter(q=>q.hasPDF&&!q.analysisAt);
 if(!pending.length){toast('沒有待分析的 PDF');return}
 if(!confirm(`將以下 ${pending.length} 篇論文的擷取文字傳送至 ${providerName()}（${config.model}），使用你的 API 額度。服務錯誤最多重試 2 次，輸出過長會調整或拆段，可能增加 API 用量。片段進度保存在電腦；金鑰不寫入磁碟。\n\n${pending.map(q=>q.title).join('\n')}\n\n開始分析？`))return;
 const results=[],snapshot={...config};
 await job('準備批次分析…',async signal=>{
  for(let i=0;i<pending.length;i++){
   const q=pending[i];if(signal.aborted){for(const remaining of pending.slice(i))results.push({title:remaining.title,status:'未處理',message:'已取消'});break}
   try{
    await ws.pdf(p,q);const pages=await ws.pages(p,q);
    if(!pages.some(pg=>pg.text.trim()))throw Error('沒有可擷取文字，需先 OCR');
    const result=await analyzePaper(analysisConfig(p,q,snapshot),q,pages,text=>progress(`${i+1}/${pending.length} · ${q.title}：${text}`),signal);
    if(signal.aborted)throw Error('已取消，未儲存此篇分析');
    await ws.saveAnalysis(p,q,result,reportMarkdown(q.title,result,p.papers));
    results.push({title:q.title,status:'成功',message:'分析及引用已儲存，仍需核對語意'});
   }catch(e){results.push({title:q.title,status:'失敗',message:e.message});
    // Stop on API/network failures instead of repeatedly making billable calls.
    for(const remaining of pending.slice(i+1))results.push({title:remaining.title,status:'未處理',message:'前一篇未完成；修正問題後可再次分析'});
    break;
   }
  }
 });
 $('#bulkSummary').textContent=['成功','失敗','未處理'].map(k=>k+' '+results.filter(r=>r.status===k).length).join(' · ');
 $('#bulkResultText').textContent=results.map(r=>`${r.status}｜${r.title}｜${r.message}`).join('\n');
 $('#bulkResult').querySelector('h2').textContent='批次分析結果';$('#bulkResult').showModal();
}



function analysisConfig(p,q=null,base=config){return {...base,checkpoint:{load:()=>ws.loadProgress(p,q),save:state=>ws.saveProgress(p,q,state)}}}
function showAnalysisError(error){$('#analysisError')?.remove();const box=document.createElement('section');box.id='analysisError';box.className='notice warning';box.setAttribute('role','alert');const text=document.createElement('p');text.textContent=error.message;const hint=document.createElement('p');hint.textContent='已完成片段保留在研究庫。再次分析可接續；更換模型或原文會重新分析。';const close=document.createElement('button');close.textContent='關閉';close.onclick=()=>box.remove();box.append(text,hint,close);$('#job').after(box)}

